import{sideIRSelection}from'./side-ir-service-state.js';
import{SIDE_IR_SERVICE_SOURCE}from'./side-ir-service-source.js';
const BANK={{BANK}};
const references=(family,i)=>{const body=family==='plus'?'sideIRPlusBody':'sideIRR1Body';return[[body,'sideIROldBoard'],['sideIRNewBoard','sideIRM2'],['lcd'],['lcd','bedSupport'],['sideIRHandleRear'],[52,'sideIRRivetPin0'],[body,'sideIROldBoard','sideIRM2'],['sideIRNewBoard'],['sideIRNewBoard','sideIRPlug'],[body,'sideIRNewBoard','sideIRM2'],[52,body],['sideIRHandleRear','sideIRInputTube'],['lcd'],['lcd','sideIRInputTube'],[body,'sideIRInputTube','lcd']][i];};
export const SIDE_IR_SERVICE_TASK={id:'side-ir-replacement',sideIRService:true,category:1,revision:1,title:['側面IRフィラメントセンサーの交換','Replace the side IR filament sensor','Výměna bočního IR senzoru filamentu','Seitlichen IR-Filamentsensor ersetzen'],interval:['基板の交換時','When replacing the board','Při výměně desky','Beim Austausch der Platine'],source:"https://help.prusa3d.com/guide/how-to-replace-the-side-filament-sensor-core-one_408981",get steps(){return BANK[sideIRSelection().family].map((s,i)=>({...s,id:'side-ir-'+s.id,number:i+1,officialId:SIDE_IR_SERVICE_SOURCE.steps[i].id,officialStep:SIDE_IR_SERVICE_SOURCE.steps[i].number,source:SIDE_IR_SERVICE_SOURCE.steps[i].source,wrapperOfficialId:s.id,refs:references(sideIRSelection().family,i),sourcePhotos:SIDE_IR_SERVICE_SOURCE.steps[i].images,supplementalSources:(SIDE_IR_SERVICE_SOURCE.steps[i].supplementalSources||[]).map(r=>({url:r.source||r.url,label:r.label||['関連する公式手順（英語）','Related official step (English)','Související oficiální krok (anglicky)','Zugehöriger offizieller Schritt (Englisch)']})),...(i===2?{firmwareActions:['unload','cooldown']}:i===3?{firmwareActions:['moveZ']}:{})}));}};

